<?php

namespace App\Models;

use App\Enums\GradeType;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Validation\ValidationException;

/**
 * یک نمرهٔ خام.
 *
 * «بیست نمرهٔ تکلیف» بیست سطر Grade است، نه یک ستون. نگهداری فقط نمرهٔ
 * تجمیعی یعنی از دست رفتن ریزنمرات، و کارنامه بدون آن قابل بازسازی نیست.
 */
class Grade extends Model
{
    use HasFactory;

    protected $fillable = [
        'student_id',
        'course_id',
        'user_id',
        'type',
        'title',
        'score',
        'max_score',
        'graded_at',
        'notes',
    ];

    protected function casts(): array
    {
        return [
            'type' => GradeType::class,
            'score' => 'decimal:2',
            'max_score' => 'decimal:2',
            'graded_at' => 'date',
        ];
    }

    public function student(): BelongsTo
    {
        return $this->belongsTo(Student::class);
    }

    public function course(): BelongsTo
    {
        return $this->belongsTo(Course::class);
    }

    /** استادی که نمره را ثبت کرده. */
    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }

    protected static function booted(): void
    {
        static::saving(function (self $grade) {
            if ((float) $grade->max_score <= 0) {
                throw ValidationException::withMessages([
                    'max_score' => 'نمرهٔ حداکثر باید بیشتر از صفر باشد.',
                ]);
            }

            // نمرهٔ بیشتر از حداکثر یعنی نمرهٔ غلط ثبت شده؛ سیستم نباید آن را
            // بپذیرد و بعد در کارنامه عددی بالاتر از ۲۰ نشان دهد
            if ((float) $grade->score > (float) $grade->max_score) {
                throw ValidationException::withMessages([
                    'score' => 'نمره نمی‌تواند از حداکثر بیشتر باشد.',
                ]);
            }

            if ((float) $grade->score < 0) {
                throw ValidationException::withMessages([
                    'score' => 'نمره نمی‌تواند منفی باشد.',
                ]);
            }
        });
    }

    public function typeLabel(): string
    {
        return $this->type?->label() ?? '—';
    }

    /** درصد این نمره، مثلاً ۸۵٫۰۰ */
    public function percentage(): float
    {
        return round((float) $this->score / (float) $this->max_score * 100, 2);
    }

    public function scoreLabel(): string
    {
        return to_persian_digits(number_format((float) $this->score, 2)).'/'
            .to_persian_digits(number_format((float) $this->max_score, 2));
    }

    public function gradedAtJalali(): ?string
    {
        return $this->graded_at ? jalali_date($this->graded_at) : null;
    }

    /**
     * ثبت یا اصلاح نمرهٔ یک تکلیف مشخص.
     *
     * updateOrCreate با کلید ایندکس یکتا هماهنگ است، پس دکمهٔ «ذخیره» دوباره
     * زده شود نمره را تکرار نمی‌کند.
     */
    public static function record(
        Student $student,
        Course $course,
        GradeType $type,
        string $title,
        float $score,
        ?float $maxScore = null,
        ?User $by = null,
        ?string $gradedAt = null,
    ): self {
        $maxScore ??= 20.0;

        return static::updateOrCreate(
            [
                'student_id' => $student->id,
                'course_id' => $course->id,
                'type' => $type->value,
                'title' => $title,
            ],
            [
                'score' => $score,
                'max_score' => $maxScore,
                'user_id' => $by?->id ?? auth()->id(),
                'graded_at' => $gradedAt,
            ],
        );
    }

    /** نمره‌های یک دانش‌آموز در یک دوره، برای محاسبهٔ میانگین. */
    public static function forStudentInCourse(Student $student, Course $course)
    {
        return static::query()
            ->where('student_id', $student->id)
            ->where('course_id', $course->id)
            ->get();
    }
}
<?php

namespace App\Models;

use App\Enums\Gender;
use App\Enums\Status;
use App\Rules\IranianNationalCode;
use Illuminate\Database\Eloquent\Casts\Attribute;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Database\Eloquent\Relations\HasOne;
use Illuminate\Validation\ValidationException;

class Student extends Model
{
    use HasFactory;

    protected $fillable = [
        'first_name',
        'last_name',
        'national_code',
        'father_name',
        'birth_date',
        'gender',
        'mobile',
        'phone',
        'email',
        'guardian_name',
        'guardian_mobile',
        'province',
        'city',
        'address',
        'postal_code',
    ];

    protected function casts(): array
    {
        return [
            'birth_date' => 'date',

            // cast به enum روی مقدار ناشناخته خطا می‌دهد، نه اینکه بی‌سروصدا
            // null بدهد. هر ورودی باید از Gender::rule() رد شده باشد
            'gender' => Gender::class,
        ];
    }

    /**
     * پروندهٔ آموزشی. hasOne نه belongsTo: یک دانش‌آموز یک پرونده دارد، ولی
     * ثبت پرونده اختیاری است و نباید جلوی ساخت دانش‌آموز را بگیرد.
     */
    public function profile(): HasOne
    {
        return $this->hasOne(StudentProfile::class);
    }

    /**
     * نام کامل.
     *
     * به‌صورت accessor است و نه ستون ذخیره‌شده: «علی رضایی» از «علی» و «رضایی»
     * ساخته می‌شود. اگر ذخیره می‌شد، هر تغییر نام باید دو جا را عوض می‌کرد.
     */
    public function getFullNameAttribute(): string
    {
        return trim($this->first_name.' '.$this->last_name);
    }

    public function guardians(): HasMany
    {
        return $this->hasMany(Guardian::class);
    }

    public function documents(): HasMany
    {
        return $this->hasMany(Document::class);
    }

    /** ثبت‌نام‌های دانش‌آموز در دوره‌ها. انتخاب واحد روی همین رابطه کار می‌کند. */
    public function enrollments(): HasMany
    {
        return $this->hasMany(CourseEnrollment::class);
    }

    public function attendances(): HasMany
    {
        return $this->hasMany(Attendance::class);
    }

    public function grades(): HasMany
    {
        return $this->hasMany(Grade::class);
    }

    /** رخدادهای انضباطی دانش‌آموز؛ ترتیب نمایش را صفحه تعیین می‌کند. */
    public function disciplines(): HasMany
    {
        return $this->hasMany(Discipline::class);
    }

    /** سوابق تحصیلی قبلی (رونویس)؛ یک دانش‌آموز ممکن است چند مدرسهٔ قبلی داشته باشد. */
    public function previousEnrollments(): HasMany
    {
        // کلید خارجی باید صریح باشد: لاراول از نام مدل «previous_enrollment_id»
        // حدس می‌زند که وجود ندارد و رابطه بی‌صدا خالی برمی‌گرداند
        return $this->hasMany(PreviousEnrollment::class, 'student_id');
    }

    public function invoices(): HasMany
    {
        return $this->hasMany(Invoice::class);
    }

    public function payments(): HasMany
    {
        return $this->hasMany(Payment::class);
    }

    /** مجموعهٔ همهٔ فاکتورهای دانش‌آموز، چه با دوره چه بدون. */
    public function totalPayable(): int
    {
        return (int) $this->invoices()
            ->whereNotIn('status', ['cancelled'])
            ->sum('payable');
    }

    public function totalPaid(): int
    {
        return (int) $this->payments()->sum('amount');
    }

    /** بدهی باز دانش‌آموز؛ هرگز منفی، پول اضافه طلب است نه بدهی. */
    public function outstanding(): int
    {
        return max(0, $this->totalPayable() - $this->totalPaid());
    }

    public function credit(): int
    {
        return max(0, $this->totalPaid() - $this->totalPayable());
    }

    /** سرپرستی که با او تماس گرفته می‌شود؛ اگر تعیین نشده باشد، اولی. */
    public function primaryGuardian(): HasOne
    {
        return $this->hasOne(Guardian::class)->where('is_primary', true);
    }

    /** وضعیت پرونده، بدون نیاز به null-check در هر view. */
    public function status(): Attribute
    {
        return Attribute::get(fn () => $this->profile?->status);
    }

    public function statusLabel(): string
    {
        return $this->profile?->statusLabel() ?? Status::labelFor(null);
    }

    public function genderLabel(): string
    {
        return $this->gender?->label() ?? '—';
    }

    /**
     * کد ملی هنگام ذخیره بررسی می‌شود، نه فقط در فرم.
     *
     * ایندکس یکتا جلوی دو نفر با یک کد را می‌گیرد ولی جلوی یک کد ملی که اصلاً
     * وجود ندارد را نمی‌گیرد؛ آن خطا باید همین‌جا و همین لحظه گرفته شود، وگرنه
     * داده پرت ثبت می‌شود و ماه‌ها بعد کسی نمی‌فهمد چرا.
     */
    protected static function booted(): void
    {
        static::saving(function (self $student) {
            $code = trim((string) $student->national_code);

            if ($code === '') {
                $student->national_code = null;

                return;
            }

            // normalize یک‌جا انجام می‌شود: ارقام فارسی، خط تیره و نیم‌فاصله
            // حذف می‌شوند و بعد اعتبار سنجیده می‌شود. این شکل ذخیره می‌شود تا
            // جست‌وجو و ایندکس یکتا روی یک شکل باشند.
            $normalized = IranianNationalCode::normalize($code);

            if (! IranianNationalCode::isValid($normalized)) {
                throw ValidationException::withMessages([
                    'national_code' => 'کد ملی معتبر نیست.',
                ]);
            }

            $student->national_code = $normalized;
        });
    }
