<?php

namespace App\Services;

use Illuminate\Support\Facades\File;
use Illuminate\Support\Facades\Process;
use Illuminate\Support\Str;

/**
 * تبدیل HTML به PDF با مرورگر headless.
 *
 * چرا مرورگر و نه کتابخانهٔ PDF: فارسی/RTL در PDF بدون فونتِ تعبیه‌شده میشکند،
 * و همین مرورگری که صفحه را نشان میدهد بهترین موتور چاپ آن است — دقیقاً همان
 * خروجی «ذخیره به‌صورت PDF» مرورگر، ولی سمت سرور و بدون کلیک کاربر.
 *
 * اگر مرورگری در دسترس نباشد، render() برمیگرداند null و caller بهصفحهٔ چاپی
 * برمیگردد؛ سند نباید بهخاطر نبودن یک باینری از دست برود.
 */
class BrowserPdf
{
    /** نام‌های رایج مرورگرهای headless در مسیر اجرایی. */
    private const CANDIDATES = [
        '/usr/bin/chromium',
        '/usr/bin/chromium-browser',
        '/usr/bin/google-chrome',
        '/usr/bin/google-chrome-stable',
        '/opt/google/chrome/google-chrome',
        '/snap/bin/chromium',
    ];

    /** مسیر قابل اجرای مرورگر؛ null یعنی این محیط PDF سمت سرور ندارد. */
    public function binary(): ?string
    {
        $configured = config('services.chrome.binary');

        if (is_string($configured) && $configured !== '') {
            return is_executable($configured) ? $configured : null;
        }

        foreach (self::CANDIDATES as $path) {
            if (is_executable($path)) {
                return $path;
            }
        }

        return null;
    }

    /** HTML را به بایت PDF تبدیل میکند؛ null اگر موتوری نباشد یا شکست بخورد. */
    public function render(string $html): ?string
    {
        $binary = $this->binary();

        if ($binary === null) {
            return null;
        }

        $base = storage_path('framework/pdf/'.Str::random(16));

        File::ensureDirectoryExists(dirname($base));
        File::put($base.'.html', $html);

        try {
            $result = Process::timeout(60)->run([
                $binary,
                '--headless=new',
                // کانتینر/سرویس بدون sandbox: چاپ به فایل به sandbox نیاز ندارد
                '--no-sandbox',
                '--disable-gpu',
                '--disable-dev-shm-usage',
                '--no-pdf-header-footer',
                '--print-to-pdf='.$base.'.pdf',
                'file://'.$base.'.html',
            ]);

            if (! $result->successful() || ! File::exists($base.'.pdf')) {
                return null;
            }

            return File::get($base.'.pdf');
        } finally {
            File::delete([$base.'.html', $base.'.pdf']);
        }
    }
}
```

