{"new_string":"     * @param  Collection<int, array{course: mixed, grades: Collection, hours: float, hoursLabel: string, score: float|null, status: string}>  $rows
     * @return array{courses: int, hours: float, hoursLabel: string, average: float|null, status: string}
     */
    public function summary(Collection $rows): array
    {
        $scores = $rows->pluck('score')->filter(fn ($score) => $score !== null);
        $hours = (float) $rows->sum('hours');

        // تا وقتی هیچ نمرهای نیست، وضعیت کلی هم «فاقد سابقه» است — حتی اگر
        // یک دوره مردودیِ نمرهندار هم نباشد چیزی برای قضاوت وجود ندارد
        $status = self::STATUS_NO_RECORD;

        if ($scores->isNotEmpty()) {
            $status = $rows->contains(fn (array $row) => $row['status'] === self::STATUS_FAIL)
                ? self::STATUS_FAIL
                : self::STATUS_PASS;
        }

        return [
            'courses' => $rows->count(),
            'hours' => $hours,
            'hoursLabel' => $this->hoursLabel($hours),
            'average' => $scores->isEmpty() ? null : round($scores->sum() / $scores->count(), 2),
            'status' => $status,
        ];
    }","old_string":"     * @param  Collection<int, array{course: mixed, grades: Collection, hours: float, score: float|null, status: string}>  $rows
